#include <stdio.h>

int main() {
    long long T,B,S,W,L,D,C,M,A,P,E;
    char mask[11];

    scanf("%lld %lld %lld %lld %lld %lld %lld %lld %lld %lld %lld",
          &T,&B,&S,&W,&L,&D,&C,&M,&A,&P,&E);
    scanf("%s", mask);

    long long vals[10];

    vals[0] = (mask[0]=='1') ? T * B : 0;

    if (mask[1]=='1' && vals[0]>0) vals[1] = vals[0] * S; else vals[1]=0;
    if (mask[2]=='1' && vals[1]>0) vals[2] = vals[1] * W; else vals[2]=0;
    if (mask[3]=='1' && vals[2]>0) vals[3] = vals[2] * L; else vals[3]=0;
    if (mask[4]=='1' && vals[3]>0) vals[4] = vals[3] * D; else vals[4]=0;
    if (mask[5]=='1' && vals[4]>0) vals[5] = vals[4] * C; else vals[5]=0;
    if (mask[6]=='1' && vals[5]>0) vals[6] = vals[5] * M; else vals[6]=0;
    if (mask[7]=='1' && vals[6]>0) vals[7] = vals[6] * A; else vals[7]=0;
    if (mask[8]=='1' && vals[7]>0) vals[8] = vals[7] * P; else vals[8]=0;
    if (mask[9]=='1' && vals[8]>0) vals[9] = vals[8] * E; else vals[9]=0;

    for(int i=0;i<10;i++) {
        printf("%lld\n", vals[i]);
    }

    return 0;
}
